package br.pucminas.iceibank.util;
import br.pucminas.iceibank.model.Evento; import com.fasterxml.jackson.databind.ObjectMapper; import java.nio.file.*; import java.util.*; import java.util.stream.Stream;
public class MesclarLogs { public static void main(String[] args)throws Exception{Path pasta=resolverPastaDados();ObjectMapper mapper=new ObjectMapper();List<Evento> eventos=new ArrayList<>();if(!Files.exists(pasta)){System.out.println("Pasta data ainda não existe.");return;}try(Stream<Path> arqs=Files.list(pasta)){for(Path a:arqs.filter(x->x.getFileName().toString().startsWith("eventos-agencia-")&&x.toString().endsWith(".jsonl")).toList())for(String l:Files.readAllLines(a))if(!l.isBlank())eventos.add(mapper.readValue(l,Evento.class));}eventos.sort(Comparator.comparing(Evento::horaParede));System.out.println("=== Linha do tempo (ordenada por hora de parede) ===");for(Evento e:eventos)System.out.printf("[%s] vetor=%s %s %s%n",e.agencia(),Arrays.toString(e.timestampVetorial()),e.tipo(),mapper.writeValueAsString(e.detalhes()));System.out.println("\n=== Pares de eventos CONCORRENTES entre agências diferentes ===");boolean achou=false;for(int i=0;i<eventos.size();i++)for(int j=i+1;j<eventos.size();j++){Evento a=eventos.get(i),b=eventos.get(j);if(a.agencia().equals(b.agencia()))continue;if(comparar(a.timestampVetorial(),b.timestampVetorial()).equals("CONCORRENTES")){achou=true;System.out.printf("[%s] %s %s x [%s] %s %s%n",a.agencia(),a.tipo(),Arrays.toString(a.timestampVetorial()),b.agencia(),b.tipo(),Arrays.toString(b.timestampVetorial()));}}if(!achou)System.out.println("(nenhum par concorrente encontrado - gere eventos independentes em agências diferentes)");}
 static String comparar(int[] a,int[] b){boolean aleb=true,blea=true;for(int i=0;i<a.length;i++){if(a[i]>b[i])aleb=false;if(b[i]>a[i])blea=false;}if(aleb&&blea)return "IGUAIS";if(aleb)return "ANTES";if(blea)return "DEPOIS";return "CONCORRENTES";}
 private static Path resolverPastaDados(){String d=System.getenv("ICEIBANK_DATA_DIR");if(d!=null&&!d.isBlank())return Path.of(d).toAbsolutePath().normalize();Path a=Path.of(System.getProperty("user.dir")).toAbsolutePath().normalize();if(Files.exists(a.resolve("pom.xml")))return a.resolve("data");if(Files.exists(a.resolve("agencia/pom.xml")))return a.resolve("agencia/data");return a.resolve("data");}}
